def scc(N, G, RG):
    order = []
    used = [0]*N
    group = [None]*N
    def dfs(s):
        used[s] = 1
        q = deque([s])
        tmp = deque([s])
        while q:
            s = q.pop()
            for t in G[s]:
                if not used[t]:
                    used[t] = 1
                    q.append(t)
                    tmp.append(t)
        while tmp:
            order.append(tmp.pop())
    def rdfs(s, col):
        group[s] = col
        used[s] = 1
        q = deque([s])
        while q:
            s = q.pop()
            for t in RG[s]:
                if not used[t]:
                    q.append(t)
                    used[t] = 1
                    group[t] = col
    for i in range(N):
        if not used[i]:
            dfs(i)
    used = [0]*N
    label = 0
    for s in reversed(order):
        if not used[s]:
            rdfs(s, label)
            label += 1
    return label, group

def construct(N, G, label, group):
    G0 = [set() for i in range(label)]
    GP = [[] for i in range(label)]
    for v in range(N):
        lbs = group[v]
        for w in G[v]:
            lbt = group[w]
            if lbs == lbt:
                continue
            G0[lbs].add(lbt)
        GP[lbs].append(v + 1)
    return G0, GP

